<?php
use App\Models\SalesInvoice; use App\Support\AuthorizationScope; use function Livewire\Volt\{computed,layout,state};
layout('layouts.app'); state(['search'=>'','customer_id'=>'']);
$invoices=computed(function(){ $u=auth()->user();$q=SalesInvoice::withoutGlobalScopes()->with(['sale','customer'])->where('company_id',$u->company_id);if(AuthorizationScope::scopeFor($u,'report_scope',AuthorizationScope::BRANCH)!==AuthorizationScope::COMPANY)$q->whereHas('sale',fn($s)=>$s->where('branch_id',$u->branch_id));return $q->when($this->customer_id,fn($x)=>$x->where('customer_id',$this->customer_id))->when($this->search,fn($x)=>$x->where(fn($s)=>$s->where('invoice_number','like',"%{$this->search}%")->orWhereHas('customer',fn($c)=>$c->where('name','like',"%{$this->search}%"))))->latest()->paginate(20);});
?>
<div><x-page-header title="Customer Invoices" description="Final invoices generated from quotation conversions and direct sales." :breadcrumbs="['Dashboard'=>route('dashboard'),'Invoices'=>null]"/><x-card><input wire:model.live.debounce.300ms="search" placeholder="Invoice or customer" class="mb-4 w-full rounded-xl border-slate-200 md:w-96 dark:bg-navy-950"><x-table :headers="['Invoice','Sale','Customer','Source','Total','Balance','']">@forelse($this->invoices as $i)<tr><td class="px-4 py-3 font-black">{{ $i->invoice_number }}</td><td class="px-4 py-3"><a href="{{ route('sales.show',$i->sale) }}" wire:navigate>{{ $i->sale->sale_number }}</a></td><td class="px-4 py-3">{{ $i->customer->name }}</td><td class="px-4 py-3">{{ $i->source_type==='direct_sale'?'Direct Sale':'Quotation' }}</td><td class="px-4 py-3">{{ \App\Support\NumberFormatter::money($i->sale->total_amount) }}</td><td class="px-4 py-3">{{ \App\Support\NumberFormatter::money($i->sale->balance_amount) }}</td><td class="px-4 py-3"><a href="{{ route('invoices.pdf',$i) }}" class="font-bold text-build-orange">PDF</a></td></tr>@empty<tr><td colspan="7" class="px-4 py-10 text-center text-slate-500">No invoices found.</td></tr>@endforelse</x-table><div class="mt-4">{{ $this->invoices->links() }}</div></x-card></div>
